import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Una prima determinazione della lunghezza della circonferenza","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fr/frd.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fr/frd.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fr/frd.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="una-prima-determinazione-della-lunghezza-della-circonferenza" tabindex="-1">Una prima determinazione della lunghezza della circonferenza <a class="header-anchor" href="#una-prima-determinazione-della-lunghezza-della-circonferenza" aria-label="Permalink to “Una prima determinazione della lunghezza della circonferenza”">​</a></h1><p>Cerchiamo, intuitivamente di capire quanto &quot;grosso modo&quot; può misurare la circonferenza di raggio dato <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi></mrow><annotation encoding="application/x-tex">r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span>.</p><p>Considero una circonferenza di raggio <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>r</mi></mrow><annotation encoding="application/x-tex">r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> e ne considero l&#39;esagono regolare inscritto e il quadrato circoscritto.</p><p>Il quadrato ha il lato di misura <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn><mi>r</mi></mrow><annotation encoding="application/x-tex">2r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span> essendo tale lato congruente al diametro della circonferenza.</p><p>Quindi avremo che il perimetro del quadrato vale:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mtext>Perimetro</mtext><mo>=</mo><mn>2</mn><mi>p</mi><mo>=</mo><mn>4</mn><mo>⋅</mo><mn>2</mn><mi>r</mi><mo>=</mo><mn>8</mn><mi>r</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{\\text{Perimetro} = 2p = 4 \\cdot 2r = 8r} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">Perimetro</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord" style="color:red;">2</span><span class="mord mathnormal" style="color:red;">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin" style="color:red;">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">2</span><span class="mord mathnormal" style="margin-right:0.0278em;color:red;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">8</span><span class="mord mathnormal" style="margin-right:0.0278em;color:red;">r</span></span></span></span></span></p><p>L&#39;esagono regolare inscritto in una circonferenza ha il lato congruente al raggio della circonferenza stessa.</p><p>Pertanto l&#39;esagono avrà perimetro di misura:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mtext>Perimetro</mtext><mo>=</mo><mn>2</mn><mi>p</mi><mo>=</mo><mn>6</mn><mo>⋅</mo><mi>r</mi><mo>=</mo><mn>6</mn><mi>r</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{\\text{Perimetro} = 2p = 6 \\cdot r = 6r} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">Perimetro</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord" style="color:red;">2</span><span class="mord mathnormal" style="color:red;">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">6</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin" style="color:red;">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;color:red;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">6</span><span class="mord mathnormal" style="margin-right:0.0278em;color:red;">r</span></span></span></span></span></p><p>La circonferenza avrà una lunghezza che dipenderà dal suo diametro (se varia il diametro varia anche la circonferenza) chiamiamo tale lunghezza:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mtext>Misura\xA0circonferenza</mtext><mo>=</mo><mtext>numero</mtext><mo>⋅</mo><mn>2</mn><mi>r</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{\\text{Misura circonferenza} = \\text{numero} \\cdot 2r} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">Misura\xA0circonferenza</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4445em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">numero</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin" style="color:red;">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">2</span><span class="mord mathnormal" style="margin-right:0.0278em;color:red;">r</span></span></span></span></span></p><p>e la misura della circonferenza sarà minore del perimetro del quadrato ma maggiore del perimetro dell&#39;esagono:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mn>6</mn><mi>r</mi><mo>&lt;</mo><mtext>numero</mtext><mo>⋅</mo><mn>2</mn><mi>r</mi><mo>&lt;</mo><mn>8</mn><mi>r</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{6r &lt; \\text{numero} \\cdot 2r &lt; 8r} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6835em;vertical-align:-0.0391em;"></span><span class="mord" style="color:red;">6</span><span class="mord mathnormal" style="margin-right:0.0278em;color:red;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.4445em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">numero</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin" style="color:red;">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6835em;vertical-align:-0.0391em;"></span><span class="mord" style="color:red;">2</span><span class="mord mathnormal" style="margin-right:0.0278em;color:red;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">8</span><span class="mord mathnormal" style="margin-right:0.0278em;color:red;">r</span></span></span></span></span></p><p>divido tutti i termini di questa disuguaglianza per <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn><mi>r</mi></mrow><annotation encoding="application/x-tex">2r</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span></span></span></span>, cioè per il diametro.</p><blockquote><p>vedi teoria della misura: equivale a dire &quot;misuro la circonferenza rispetto al suo diametro&quot;</p></blockquote><p>ottengo:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mn>3</mn><mo>&lt;</mo><mtext>numero</mtext><mo>&lt;</mo><mn>4</mn></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{3 &lt; \\text{numero} &lt; 4} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6835em;vertical-align:-0.0391em;"></span><span class="mord" style="color:red;">3</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">numero</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">4</span></span></span></span></span></p><p>Quindi la misura della circonferenza rispetto al suo diametro è un numero compreso fra <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>3</mn></mrow><annotation encoding="application/x-tex">3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>4</mn></mrow><annotation encoding="application/x-tex">4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span>: tale numero, per convenzione, verrà chiamato <strong>pi greco</strong> e, per indicarlo, verrà utilizzato il simbolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>π</mi></mrow><annotation encoding="application/x-tex">\\pi</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span></span></span></span>.</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mn>3</mn><mo>&lt;</mo><mi>π</mi><mo>&lt;</mo><mn>4</mn></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{3 &lt; \\pi &lt; 4} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6835em;vertical-align:-0.0391em;"></span><span class="mord" style="color:red;">3</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;color:red;">π</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">4</span></span></span></span></span></p><p>Ed indicheremo la misura della lunghezza della circonferenza come:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mstyle mathcolor="red"><mtext>Misura\xA0circonferenza</mtext><mo>=</mo><mn>2</mn><mi>π</mi><mi>r</mi></mstyle></mrow><annotation encoding="application/x-tex">\\textcolor{red}{\\text{Misura circonferenza} = 2\\pi r} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord text" style="color:red;"><span class="mord" style="color:red;">Misura\xA0circonferenza</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel" style="color:red;">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord" style="color:red;">2</span><span class="mord mathnormal" style="margin-right:0.0359em;color:red;">π</span><span class="mord mathnormal" style="margin-right:0.0278em;color:red;">r</span></span></span></span></span></p>`,21)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};